@application.get(
    "/api/share-usage", response_model=list[ShareUsageRecord]
)
def share_usage(
    share_id: str | None = Query(default=None),
    from_time: str | None = Query(default=None, alias="from"),
    to_time: str | None = Query(default=None, alias="to"),
    limit: int = Query(default=50, ge=1, le=100),
) -> list[dict]:
    # Same validation contract as the audit endpoint: a blank share_id,
    # a non-timezone timestamp, a non-half-open window or an out-of-range
    # limit is a 422; an unknown share_id is a valid filter matching
    # nothing and answers 200 with an empty array.
    if share_id is not None:
        share_id = share_id.strip()
        if not share_id:
            raise HTTPException(
                status_code=422, detail="share_id 必须是非空字符串"
            )
    start = _parse_access_event_time(from_time, "from") if from_time is not None else None
    end = _parse_access_event_time(to_time, "to") if to_time is not None else None
    if start is not None and end is not None and start >= end:
        raise HTTPException(status_code=422, detail="from 必须早于 to")
    # Read-only summary of the two share tables in one transaction: no
    # event is recorded by this call, and share, quota, budget and
    # release state are all untouched.
    return summarize_share_usage(
        path,
        share_id=share_id,
        start=start,
        end=end,
        limit=limit,
    )

