const USAGE_FIELDS = ['share_id', 'dataset_id', 'status', 'max_accesses', 'served_count',
  'remaining_accesses', 'event_count', 'result_count',
  'served', 'expired', 'revoked', 'superseded', 'quota_exhausted', 'last_accessed_at'];
const USAGE_OUTCOMES = [
  ['served', 'served 成功'],
  ['quota_exhausted', '配额用尽'],
  ['expired', '已过期'],
  ['revoked', '已撤销'],
  ['superseded', '旧令牌'],
];

function describeRemaining(row) {
  if (row.max_accesses === null || row.max_accesses === undefined) {
    return `上限 不限 · 已用 ${row.served_count ?? 0} · 剩余 不限`;
  }
  const remaining = row.remaining_accesses === null || row.remaining_accesses === undefined
    ? Math.max(0, row.max_accesses - (row.served_count ?? 0))
    : row.remaining_accesses;
  return `上限 ${row.max_accesses} · 已用 ${row.served_count ?? 0} · 剩余 ${remaining}`;
}

function usageCountCell(value, label) {
  const span = document.createElement('span');
  span.className = `usage-count${value ? ' nonzero' : ''}`;
  const strong = document.createElement('strong');
  strong.textContent = value;
  span.append(strong, ` ${label}`);
  return span;
}

function renderShareUsage(rows) {
  const container = document.getElementById('usage-results');
  container.textContent = '';
  if (!rows.length) {
    const empty = document.createElement('p');
    empty.className = 'empty';
    empty.textContent = '没有符合条件的分享。';
    container.append(empty);
    return;
  }
  const zeroCount = rows.filter(row => !row.event_count).length;
  const table = document.createElement('table');
  table.className = 'audit-table';
  const thead = document.createElement('thead');
  const headRow = document.createElement('tr');
  for (const label of ['状态', 'share_id', '配额（已用/剩余）', '窗口事件', '返回条数合计',
      'served', '配额用尽', 'expired', 'revoked', 'superseded', '最近访问时间']) {
    const th = document.createElement('th');
    th.textContent = label;
    headRow.append(th);
  }
  thead.append(headRow);
  const tbody = document.createElement('tbody');
  for (const row of rows) {
    const tr = document.createElement('tr');
    if (!row.event_count) tr.className = 'usage-zero';
    const statusTd = document.createElement('td');
    const statusMeta = STATUS_LABELS[row.status] || STATUS_LABELS.active;
    const badge = document.createElement('span');
    badge.className = `status-badge ${statusMeta.className}`;
    badge.textContent = statusMeta.label;
    statusTd.append(badge);
    const idTd = document.createElement('td');
    idTd.textContent = row.share_id;
    const quotaTd = document.createElement('td');
    quotaTd.textContent = describeRemaining(row);
    const eventsTd = document.createElement('td');
    eventsTd.textContent = row.event_count
      ? String(row.event_count)
      : '0（窗口内零事件）';
    const resultTd = document.createElement('td');
    resultTd.textContent = String(row.result_count);
    const servedTd = document.createElement('td');
    servedTd.append(usageCountCell(row.served, ''));
    const exhaustedTd = document.createElement('td');
    exhaustedTd.textContent = String(row.quota_exhausted);
    const expiredTd = document.createElement('td');
    expiredTd.textContent = String(row.expired);
    const revokedTd = document.createElement('td');
    revokedTd.textContent = String(row.revoked);
    const supersededTd = document.createElement('td');
    supersededTd.textContent = String(row.superseded);
    const lastTd = document.createElement('td');
    lastTd.textContent = row.last_accessed_at
      ? new Date(row.last_accessed_at).toLocaleString()
      : '—';
    tr.append(statusTd, idTd, quotaTd, eventsTd, resultTd, servedTd,
      exhaustedTd, expiredTd, revokedTd, supersededTd, lastTd);
    tbody.append(tr);
  }
  table.append(thead, tbody);
  container.append(table);
  if (zeroCount) {
    const note = document.createElement('p');
    note.className = 'empty';
    note.style.marginTop = '10px';
    note.textContent = `其中 ${zeroCount} 个分享在所选窗口内没有访问事件（计数为 0、最近访问时间为空），仍按创建时间倒序列出。`;
    container.append(note);
  }
}

async function loadShareUsage() {
  const message = document.getElementById('usage-message');
  const params = new URLSearchParams();
  const shareId = document.getElementById('usage-share-id').value.trim();
  if (shareId) params.set('share_id', shareId);
  const fromIso = localInputToIso(document.getElementById('usage-from').value);
  const toIso = localInputToIso(document.getElementById('usage-to').value);
  if (fromIso) params.set('from', fromIso);
  if (toIso) params.set('to', toIso);
  const limitRaw = document.getElementById('usage-limit').value;
  const limit = Number.parseInt(limitRaw, 10);
  if (limitRaw === '' || !Number.isInteger(limit) || limit < 1 || limit > 100) {
    message.className = 'error';
    message.textContent = '查询失败：limit 必须是 1–100 的整数。';
    return;
  }
  params.set('limit', String(limit));
  if (fromIso && toIso && new Date(fromIso) >= new Date(toIso)) {
    message.className = 'error';
    message.textContent = '查询失败：起始时间必须早于结束时间。';
    return;
